G=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
R,C=len(G),len(G[0]); seen=set()
for r in range(R):
 for c in range(C):
  if G[r][c]==0 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); comp=[];edge=False
   while q:
    x,y=q.pop();comp.append((x,y));edge|=x in (0,R-1) or y in (0,C-1)
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and G[a][b]==0 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
   print(len(comp),edge,comp)
